role:
.dcw-who-card { position: relative; overflow: hidden; padding: clamp(24px, 3vw, 36px); border-radius: 20px; }
.dcw-who-card.is-mine { background-color: #0f6e68; background-image: radial-gradient(circle at 100% 0%, rgba(111,217,203,0.35), transparent 50%), linear-gradient(150deg, #0f6e68, #084844); box-shadow: 0 26px 50px -26px rgba(6,43,42,0.65); color: #ffffff; }
.dcw-who-card.is-team { border: 1px solid #e2e2e2; background-color: #ffffff; background-image: radial-gradient(circle, rgba(15,110,104,0.09) 1px, transparent 1.5px); background-size: 18px 18px; box-shadow: 0 18px 40px -30px rgba(0,0,0,0.35); }
.dcw-role-head { margin-bottom: 22px; padding-bottom: 18px; border-bottom: 1px solid rgba(15,110,104,0.18); }
.dcw-role-kicker { margin-bottom: 6px; color: #0f6e68; font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.dcw-role-kicker.is-mine { color: #6fd9cb; }
.dcw-role-title { margin-top: 0; margin-bottom: 0; color: #111111; font-size: clamp(22px, 2.2vw, 26px); font-weight: 700; line-height: 1.2; }
.dcw-role-title.is-mine { color: #ffffff; }
.dcw-team-dots { display: flex; grid-column-gap: 6px; margin-top: 14px; }
.dcw-team-dot { width: 22px; height: 22px; border: 2px solid #ffffff; border-radius: 50%; background-color: #cfe6e2; box-shadow: 0 0 0 1px #b9ddd6; }
.dcw-team-dot.is-me { background-color: #0f6e68; box-shadow: 0 0 0 1px #0f6e68; }
.dcw-role-list { display: flex; flex-direction: column; grid-row-gap: 14px; margin-top: 0; margin-bottom: 0; padding-left: 0; list-style-type: none; }
.dcw-role-item { display: flex; align-items: flex-start; grid-column-gap: 14px; }
.dcw-role-n { flex: none; display: flex; justify-content: center; align-items: center; width: 34px; height: 34px; border: 1.5px solid #0f6e68; border-radius: 10px; background-color: #ffffff; color: #0f6e68; font-size: 13px; font-weight: 700; }
.dcw-role-n.is-mine { border-color: transparent; background-color: rgba(255,255,255,0.14); color: #ffffff; }
.dcw-role-text { padding-top: 5px; color: #3d3d3d; font-size: 15.5px; line-height: 1.55; }
.dcw-role-text.is-mine { color: rgba(255,255,255,0.92); }

r1:
.dcw-rc { position: relative; overflow: hidden; padding: clamp(24px, 3vw, 36px); border-radius: 20px; }
.dcw-rc.is-wins { background-color: #062b2a; background-image: radial-gradient(circle at 100% 0%, rgba(111,217,203,0.28), transparent 55%), linear-gradient(160deg, #0a3b39, #041d1c); box-shadow: 0 26px 50px -26px rgba(6,43,42,0.7); }
.dcw-rc.is-opps { border: 1.5px dashed #9cc9c2; background-color: #ffffff; background-image: repeating-linear-gradient(135deg, rgba(15,110,104,0.045) 0px, rgba(15,110,104,0.045) 2px, transparent 2px, transparent 12px); }
.dcw-rc-head { display: flex; align-items: center; grid-column-gap: 14px; margin-bottom: 20px; padding-bottom: 18px; border-bottom: 1px solid #e2e2e2; }
.dcw-rc-head.is-wins { border-bottom-color: rgba(255,255,255,0.14); }
.dcw-rc-icon { flex: none; display: flex; justify-content: center; align-items: center; width: 48px; height: 48px; border-radius: 14px; font-size: 22px; font-weight: 700; }
.dcw-rc-icon.is-wins { background-color: #6fd9cb; color: #062b2a; }
.dcw-rc-icon.is-opps { border: 1px solid #b9ddd6; background-color: #e3f2ef; color: #0a524e; }
.dcw-rc-titles { flex: 1; }
.dcw-rc-kicker { color: #0f6e68; font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.dcw-rc-kicker.is-wins { color: #6fd9cb; }
.dcw-rc-title { margin-top: 2px; margin-bottom: 0; color: #111111; font-size: 24px; font-weight: 700; line-height: 1.2; }
.dcw-rc-title.is-wins { color: #ffffff; }
.dcw-rc-count { color: rgba(15,110,104,0.28); font-size: 44px; font-weight: 700; line-height: 1; }
.dcw-rc-count.is-wins { color: rgba(111,217,203,0.35); }
.dcw-rc-list { display: flex; flex-direction: column; grid-row-gap: 10px; margin-top: 0; margin-bottom: 0; padding-left: 0; list-style-type: none; }
.dcw-rc-item { display: flex; align-items: flex-start; grid-column-gap: 12px; padding: 12px 14px; border-radius: 12px; }
.dcw-rc-item.is-wins { border: 1px solid rgba(255,255,255,0.08); background-color: rgba(255,255,255,0.06); }
.dcw-rc-item.is-opps { border: 1px solid #e2e2e2; background-color: #ffffff; }
.dcw-rc-mark { flex: none; display: flex; justify-content: center; align-items: center; width: 24px; height: 24px; margin-top: 1px; border-radius: 50%; font-size: 13px; font-weight: 700; }
.dcw-rc-mark.is-wins { background-color: #6fd9cb; color: #062b2a; }
.dcw-rc-mark.is-opps { border: 1.5px solid #0f6e68; background-color: #ffffff; color: #0f6e68; }
.dcw-rc-text { font-size: 15px; line-height: 1.55; }
.dcw-rc-text.is-wins { color: rgba(255,255,255,0.9); }
.dcw-rc-text.is-opps { color: #3d3d3d; }
.dcw-callout.is-light { margin-top: 20px; background-color: #6fd9cb; }
.dcw-callout-num.is-light { color: #062b2a; }
.dcw-callout-text.is-light { color: #062b2a; }

