wf:
.dcw-wf { display: grid; grid-template-columns: 5fr 7fr; grid-column-gap: clamp(28px, 5vw, 64px); grid-row-gap: 28px; align-items: center; }
.dcw-wf-list { display: flex; flex-direction: column; grid-row-gap: 8px; margin-top: 18px; margin-bottom: 0; padding-left: 0; list-style-type: none; }
.dcw-wf-item { display: flex; align-items: center; grid-column-gap: 12px; padding: 10px 14px; border: 1px solid #e2e2e2; border-radius: 10px; background-color: #ffffff; color: #111111; font-size: 15px; font-weight: 500; }
.dcw-wf-n { flex: none; color: #0f6e68; font-size: 13px; font-weight: 700; }
.dcw-wf-frame { position: relative; }
.dcw-wf-paper { padding: clamp(10px, 1.6vw, 18px); border: 1px solid #e2e2e2; border-radius: 16px; background-color: #ffffff; background-image: linear-gradient(rgba(15,110,104,0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(15,110,104,0.06) 1px, transparent 1px); background-size: 22px 22px; box-shadow: 0 24px 48px -28px rgba(6,43,42,0.45); transform: rotate(-1deg); }
.dcw-wf-img { display: block; width: 100%; aspect-ratio: 16 / 10; object-fit: cover; border-radius: 10px; }
@media screen and (max-width: 991px) { .dcw-wf { grid-template-columns: 1fr; } }
